<?php
namespace App\Interfaces\Http\Controllers\Api\V1\Fraud;use App\Application\Audit\AuditWriter;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;
/** REQ-DUP-009: risk-alerts is canonical (FraudReviewService); trust/fraud-alerts* are deprecated aliases of alert()/decide(). */
final class RiskAlertController{use \App\Interfaces\Http\Controllers\Concerns\AuthorizesSensitiveActions;
public function createRule(Request$r,AuditWriter$audit){$d=$r->validate(['code'=>'required|string|max:80','scope'=>'required|in:PAYMENT,QUOTE,POLICY,CLAIM,COMMISSION,IDENTITY','risk_points'=>'required|integer|min:1|max:100','conditions'=>'required|array','effective_from'=>'required|date','effective_until'=>'nullable|date|after:effective_from']);$version=(DB::table('fraud_rule_versions')->where('code',$d['code'])->max('version')??0)+1;$canonical=json_encode($d,JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE);$id=(string)Str::uuid();DB::table('fraud_rule_versions')->insert([...$d,'id'=>$id,'version'=>$version,'status'=>'DRAFT','conditions'=>json_encode($d['conditions']),'rule_hash'=>hash('sha256',$canonical),'created_at'=>now(),'updated_at'=>now()]);$audit->record('fraud.rule.created','fraud_rule_version',$id,['version'=>$version]);return response()->json(['data'=>['id'=>$id,'version'=>$version,'status'=>'DRAFT']],201);}
public function alert(Request$r,\App\Application\Trust\FraudReviewService$s){$perm=$this->authorizeRoutePermission($r,'risk_alert');$tenant=app(\App\Domain\Tenancy\TenantContext::class)->id();if($r->has('fraud_rule_version_id')){$d=$r->validate(['subject_type'=>'required|string|max:64','subject_id'=>'required|uuid','alert_type'=>'required|string|max:64','severity'=>'required|in:LOW,MEDIUM,HIGH,CRITICAL','signals'=>'required|array','fraud_rule_version_id'=>'required|uuid','idempotency_key'=>'required|string|max:100','review_due_at'=>'nullable|date']);$x=$this->auditedCall(fn()=>$s->alert($tenant,$d,$r->user()),$perm,'risk_alert',null);}else{$d=$r->validate(['subject_type'=>'required|in:PAYMENT,QUOTE,POLICY,CLAIM,COMMISSION,USER','subject_id'=>'required|uuid','alert_type'=>'required|string|max:64','risk_score'=>'required|integer|min:0|max:100','signals'=>'required|array|min:1']);$x=$this->auditedCall(fn()=>$s->manualAlert($tenant,$d,$r->user()),$perm,'risk_alert',null);}return$this->viaTrustAlias($r)?response()->json($x,201):response()->json(['data'=>['id'=>$x->id,'severity'=>$x->severity,'status'=>$x->status]],201);}
public function decide(Request$r,string$alert,\App\Application\Trust\FraudReviewService$s){$perm=$this->authorizeRoutePermission($r,'risk_alert',$alert);$x=\App\Models\RiskAlert::where('id',$alert)->where('tenant_id',app(\App\Domain\Tenancy\TenantContext::class)->id())->first();abort_unless($x,404);$d=$r->validate(['decision'=>'required|in:CLEARED,CONFIRMED,CONFIRMED_FRAUD,MONITOR,ESCALATED,ESCALATE_COMPLIANCE','notes'=>'required|string|max:4000']);$x=$this->auditedCall(fn()=>$s->decide($x,$d['decision'],$d['notes'],$r->user()),$perm,'risk_alert',$x->id);return$this->viaTrustAlias($r)?response()->json($x):response()->json(['data'=>['id'=>$x->id,'status'=>$x->status,'decision'=>$x->decision]]);}}
